mapper.select:
        SELECT
			reservation_id, member_id, store_id, reservation_time, guest_count,
			status, cancelled_reason, created_at
        FROM reservations
        WHERE STORE_ID = #{storeId}
        AND DATE(RESERVATION_TIME) = #{date}
        AND STATUS IN

            #{status}

        ORDER BY reservation_time ASC

mapper.insert:
INSERT INTO reservations (
    member_id, store_id, reservation_time, guest_count,
    status, cancelled_reason
) VALUES (
    #{memberId}, #{storeId}, #{reservationTime}, #{guestCount},
    #{status}, #{cancelledReason}
)

mapper.update:
UPDATE reservations
SET status = #{status}
WHERE reservation_id = #{reservationId}

UPDATE reservations
SET
    status = #{status},
    cancelled_reason = #{cancelledReason}
